package com.securetools.cli

import java.security.SecureRandom
import java.util.concurrent.atomic.AtomicLong
import kotlin.experimental.and

object FeatureFlags {
    var USE_HARDWARE_RNG: Boolean = System.getenv("USE_HARDWARE_RNG")?.toBoolean() ?: false
    var ENABLE_TOKEN_ROTATION: Boolean = System.getenv("ENABLE_TOKEN_ROTATION")?.toBoolean() ?: true
    var TOKEN_LENGTH: Int = System.getenv("TOKEN_LENGTH")?.toInt() ?: 32
    var SEED_STRATEGY: String = System.getenv("SEED_STRATEGY") ?: "system"
}

interface EntropySource {
    fun nextBytes(count: Int): ByteArray
    fun reseed(seed: Long)
}

class SystemEntropySource : EntropySource {
    private val secureRandom = SecureRandom()

    override fun nextBytes(count: Int): ByteArray {
        val bytes = ByteArray(count)
        secureRandom.nextBytes(bytes)
        return bytes
    }

    override fun reseed(seed: Long) {
        // SecureRandom handles reseeding internally
    }
}

class SeededEntropySource(initialSeed: Long) : EntropySource {
    private val state = AtomicLong(initialSeed)

    override fun nextBytes(count: Int): ByteArray {
        val bytes = ByteArray(count)
        for (i in 0 until count) {
            val current = state.getAndUpdate { s ->
                (s * 6364136223846793005L + 1442695040888963407L)
            }
            bytes[i] = ((current ushr 33) and 0xFF).toByte()
        }
        return bytes
    }

    override fun reseed(seed: Long) {
        state.set(seed)
    }
}

class EntropyPool(private val sources: List<EntropySource>) {
    private val mixingState = ByteArray(64)
    private val secureRandom = SecureRandom()

    init {
        secureRandom.nextBytes(mixingState)
    }

    fun gather(byteCount: Int): ByteArray {
        val gathered = ByteArray(byteCount)
        secureRandom.nextBytes(gathered)
        for (source in sources) {
            val contribution = source.nextBytes(byteCount)
            for (i in 0 until byteCount) {
                gathered[i] = (gathered[i].toInt() xor contribution[i].toInt()).toByte()
            }
        }
        return gathered
    }
}

class TokenGenerator private constructor(private val pool: EntropyPool) {

    companion object {
        fun create(): TokenGenerator {
            val sources = buildEntropySourceList()
            val pool = EntropyPool(sources)
            return TokenGenerator(pool)
        }

        private fun buildEntropySourceList(): List<EntropySource> {
            val sources = mutableListOf<EntropySource>()

            when (FeatureFlags.SEED_STRATEGY) {
                "system" -> {
                    sources.add(SystemEntropySource())
                }
                "mixed" -> {
                    sources.add(SystemEntropySource())
                    sources.add(SeededEntropySource(System.nanoTime()))
                }
                "deterministic" -> {
                    sources.add(SeededEntropySource(System.nanoTime()))
                }
                else -> {
                    sources.add(SystemEntropySource())
                }
            }

            if (FeatureFlags.USE_HARDWARE_RNG) {
                sources.add(SystemEntropySource())
            }

            return sources
        }
    }

    fun generateToken(): String {
        val tokenBytes = pool.gather(FeatureFlags.TOKEN_LENGTH)
        return tokenBytes.joinToString("") { "%02x".format(it and 0xFF.toByte()) }
    }

    fun generateApiKey(prefix: String = "sk"): String {
        val token = generateToken()
        return "${prefix}_${token}"
    }
}

class SessionManager {
    private val activeSessions = mutableMapOf<String, SessionInfo>()
    private val tokenGen = TokenGenerator.create()

    data class SessionInfo(
        val userId: String,
        val createdAt: Long,
        val token: String
    )

    fun createSession(userId: String): String {
        val token = tokenGen.generateApiKey("sess")
        activeSessions[token] = SessionInfo(userId, System.currentTimeMillis(), token)
        return token
    }

    fun validateSession(token: String): Boolean {
        val session = activeSessions[token] ?: return false
        if (FeatureFlags.ENABLE_TOKEN_ROTATION) {
            val age = System.currentTimeMillis() - session.createdAt
            if (age > 3600000) {
                activeSessions.remove(token)
                return false
            }
        }
        return true
    }
}

fun main(args: Array<String>) {
    val command = args.firstOrNull() ?: "generate"
    val sessionManager = SessionManager()

    when (command) {
        "generate" -> {
            val tokenGen = TokenGenerator.create()
            println("Generated token: ${tokenGen.generateToken()}")
        }
        "apikey" -> {
            val tokenGen = TokenGenerator.create()
            println("Generated API key: ${tokenGen.generateApiKey()}")
        }
        "session" -> {
            val userId = args.getOrElse(1) { "user_default" }
            val session = sessionManager.createSession(userId)
            println("Session created: $session")
        }
        else -> println("Unknown command: $command")
    }
}
